Looking at this problem, I need to:

1. Load the graph
2. Identify primary nodes (not replicas of anything)
3. Find customer-facing services deployed in reg-3
4. For each service, determine if it would be down when reg-3 fails
5. A service is down if it or any of its transitive dependencies are lost
6. A node is lost if its replica group's footprint contains only reg-3

Let me trace through the logic:
- Find replica groups (connected components via replicaOf edges)
- For each node, compute its footprint (regions where its replica group is deployed)
- A node is lost when reg-3 fails if footprint == {reg-3}
- A service is down if it's lost OR any transitive dependency is lost

```python
import json
from collections import defaultdict, deque

# Load graph
with open('graph.json', 'r') as f:
    graph = json.load(f)

# Build node lookup
nodes = {node['id']: node for node in graph['nodes']}

# Build adjacency lists for different edge types
depends_on = defaultdict(set)  # service -> dependencies
deployed_in = defaultdict(set)  # node -> regions
owned_by = defaultdict(set)
has_sla = defaultdict(set)
replica_of = defaultdict(set)  # node -> nodes it's a replica of
replica_of_reverse = defaultdict(set)  # node -> nodes that are replicas of it

for edge in graph['edges']:
    source, relation, target = edge
    if relation == 'dependsOn':
        depends_on[source].add(target)
    elif relation == 'deployedIn':
        deployed_in[source].add(target)
    elif relation == 'ownedBy':
        owned_by[source].add(target)
    elif relation == 'hasSLA':
        has_sla[source].add(target)
    elif relation == 'replicaOf':
        replica_of[source].add(target)
        replica_of_reverse[target].add(source)

# Find replica groups using union-find
parent = {}

def find(x):
    if x not in parent:
        parent[x] = x
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    px, py = find(x), find(y)
    if px != py:
        parent[px] = py

# Union all nodes connected by replicaOf
for source in replica_of:
    for target in replica_of[source]:
        union(source, target)

# Group nodes by replica group
replica_groups = defaultdict(set)
for node_id in nodes:
    root = find(node_id)
    replica_groups[root].add(node_id)

# Compute footprint for each replica group
footprint = {}
for root, group in replica_groups.items():
    regions = set()
    for node_id in group:
        regions.update(deployed_in[node_id])
    footprint[root] = regions

# Identify primary nodes (not replicas of anything)
primary_nodes = set()
for node_id in nodes:
    if node_id not in replica_of or len(replica_of[node_id]) == 0:
        primary_nodes.add(node_id)

# Find customer-facing services deployed in reg-3
cfs_in_reg3 = set()
for node in graph['nodes']:
    if node['type'] == 'CustomerFacingService' and node['id'] in primary_nodes:
        if 'reg-3' in deployed_in[node['id']]:
            cfs_in_reg3.add(node['id'])

# Determine which nodes are lost when reg-3 fails
lost_nodes = set()
for root, regions in footprint.items():
    if regions == {'reg-3'}:
        lost_nodes.update(replica_groups[root])

# For each service, check if it's down
def is_down(service_id, visited=None):
    if visited is None:
        visited = set()
    if service_id in visited:
        return False
    visited.add(service_id)

    # Check if this node is lost
    if service_id in lost_nodes:
        return True

    # Check if any dependency is down
    for dep in depends_on[service_id]:
        if is_down(dep, visited):
            return True

    return False

# Find services that are NOT down
not_down = set()
for service_id in cfs_in_reg3:
    if not is_down(service_id):
        not_down.add(service_id)

print(json.dumps({"answer_type": "set", "answer": sorted(list(not_down))}))
```

