```python
import json
from collections import defaultdict, deque

# Load graph
with open('graph.json', 'r') as f:
    graph = json.load(f)

# Build node lookup
nodes_by_id = {node['id']: node for node in graph['nodes']}

# Build adjacency lists
edges_out = defaultdict(list)  # source -> [(relation, target), ...]
edges_in = defaultdict(list)   # target -> [(relation, source), ...]

for source, relation, target in graph['edges']:
    edges_out[source].append((relation, target))
    edges_in[target].append((relation, source))

# Find replica groups using union-find
parent = {}

def find(x):
    if x not in parent:
        parent[x] = x
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    px, py = find(x), find(y)
    if px != py:
        parent[px] = py

# Union all nodes connected by replicaOf
for source, relation, target in graph['edges']:
    if relation == 'replicaOf':
        union(source, target)

# Group nodes by replica group
replica_groups = defaultdict(set)
for node_id in nodes_by_id:
    root = find(node_id)
    replica_groups[root].add(node_id)

# For each node, find its replica group and footprint
node_to_group = {}
group_footprint = {}

for node_id in nodes_by_id:
    root = find(node_id)
    node_to_group[node_id] = replica_groups[root]

for group_root, group_members in replica_groups.items():
    footprint = set()
    for member in group_members:
        # Find regions where this member is deployed
        for relation, target in edges_out[member]:
            if relation == 'deployedIn' and nodes_by_id[target]['type'] == 'Region':
                footprint.add(target)
    group_footprint[group_root] = footprint

# Identify primary nodes (not replicas)
primary_nodes = set()
for node_id in nodes_by_id:
    is_replica = False
    for relation, _ in edges_in[node_id]:
        if relation == 'replicaOf':
            is_replica = True
            break
    if not is_replica:
        primary_nodes.add(node_id)

# Find customer-facing services in reg-2
cfs_in_reg2 = set()
for node in graph['nodes']:
    if node['type'] == 'CustomerFacingService' and node['id'] in primary_nodes:
        # Check if deployed in reg-2
        for relation, target in edges_out[node['id']]:
            if relation == 'deployedIn' and target == 'reg-2':
                cfs_in_reg2.add(node['id'])
                break

# Determine which nodes are lost when reg-2 fails
lost_nodes = set()
for node_id in primary_nodes:
    root = find(node_id)
    footprint = group_footprint[root]
    if footprint == {'reg-2'}:
        lost_nodes.add(node_id)

# For each service, check if it's down
def is_service_down(service_id, lost_nodes, visited=None):
    if visited is None:
        visited = set()
    if service_id in visited:
        return False
    visited.add(service_id)

    if service_id in lost_nodes:
        return True

    # Check transitive dependencies
    for relation, target in edges_out[service_id]:
        if relation == 'dependsOn':
            if is_service_down(target, lost_nodes, visited):
                return True

    return False

# Find services that are NOT down
not_down = []
for service_id in cfs_in_reg2:
    if not is_service_down(service_id, lost_nodes):
        not_down.append(service_id)

not_down.sort()
print(json.dumps({"answer_type": "set", "answer": not_down}))
